import React, { useState, useRef } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { projectMessagesService, calendarService } from '../../services/api';
import CheatSheet, { CheatSheetModal } from '../common/CheatSheet';
import { queryKeys } from '../../hooks/useQueryApi';
import toast from 'react-hot-toast';
import GranularTimingControls from '../ui/GranularTimingControls';

const MTRForm = ({
  activeCommTab,
  colorMode,
  showMessageDropdown,
  setShowMessageDropdown,
  projects,
  availableUsers,
  usersLoading = false,
  subjects,
  currentUser,
  // Message form state
  newMessageProject,
  setNewMessageProject,
  newMessageSubject,
  setNewMessageSubject,
  newMessageCustomSubject,
  setNewMessageCustomSubject,
  newMessageText,
  setNewMessageText,
  newMessageRecipients,
  setNewMessageRecipients,
  // Task form state
  quickTaskSubject,
  setQuickTaskSubject,
  quickTaskDescription,
  setQuickTaskDescription,
  quickTaskDue,
  setQuickTaskDue,
  quickTaskAssignAll,
  setQuickTaskAssignAll,
  quickTaskAssigneeId,
  setQuickTaskAssigneeId,
  tasksProjectFilter,
  setTasksProjectFilter,
  // Reminder form state
  reminderTitle,
  setReminderTitle,
  reminderDescription,
  setReminderDescription,
  reminderWhen,
  setReminderWhen,
  reminderAllUsers,
  setReminderAllUsers,
  reminderUserIds,
  setReminderUserIds,
  remindersProjectFilter,
  setRemindersProjectFilter,
  // Callbacks
  setMessagesData,
  setFeed,
  uiProjects,
  // Granular timing props
  taskTiming,
  setTaskTiming,
  taskFollowUpTiming,
  setTaskFollowUpTiming,
  reminderTiming,
  setReminderTiming,
  reminderFollowUpTiming,
  setReminderFollowUpTiming
}) => {
  const queryClient = useQueryClient();
  const recipients = Array.isArray(availableUsers) ? availableUsers : [];
  const [isQuickModalOpen, setIsQuickModalOpen] = useState(false);
  const [showCustomerDropdown, setShowCustomerDropdown] = useState(false);

  return (
    <div className="mb-3">
      <button
        onClick={() => setShowMessageDropdown(!showMessageDropdown)}
        className={`w-full px-2 py-1.5 text-xs font-medium border rounded-lg transition-all duration-300 flex items-center justify-between ${
          showMessageDropdown
            ? 'border-brand-400 bg-brand-50 text-brand-700 shadow-soft' 
            : 'border-gray-200 bg-white/80 text-gray-700 hover:bg-white hover:border-brand-400 hover:text-brand-600'
        }`}
      >
        <span>{activeCommTab === 'messages' ? '+ Add Message' : activeCommTab === 'tasks' ? '+ Add Task' : '+ Add Reminder'}</span>
        <svg className={`w-3 h-3 transition-transform ${showMessageDropdown ? 'rotate-180' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
        </svg>
      </button>
      
      {/* Messages Form */}
      {showMessageDropdown && activeCommTab === 'messages' && (
        <div className={`p-2 border-t ${colorMode ? 'bg-[#1e293b] border-gray-600' : 'bg-gray-50 border-gray-200'}`}>
          <form onSubmit={(e) => {
            e.preventDefault();
            const finalSubject = newMessageSubject;
            if (newMessageProject && finalSubject && newMessageText.trim() && newMessageRecipients.length > 0) {
              const selectedProject = projects.find(p => p.id === parseInt(newMessageProject));
              
              // Create message using the API service
              const createMessage = async () => {
                try {
                  // Handle special "all" selection by expanding to actual user IDs
                  let recipientsToSend = Array.isArray(newMessageRecipients) ? [...newMessageRecipients] : [];
                  if (recipientsToSend.includes('all')) {
                    // Expand 'all' using the Roles API which drives the Settings -> Roles "Available Users" list
                    try {
                      const rolesRes = await import('../../services/api').then(m => m.rolesService.getUsers());
                      if (rolesRes && rolesRes.success && Array.isArray(rolesRes.data)) {
                        recipientsToSend = rolesRes.data.map(u => String(u.id));
                      } else if (Array.isArray(recipients) && recipients.length > 0) {
                        // Fallback to live users loaded by useTeamMembers
                        recipientsToSend = recipients.map(u => String(u.id));
                      } else {
                        recipientsToSend = [];
                      }
                    } catch (err) {
                      // On error, fallback to live users
                      recipientsToSend = Array.isArray(recipients) ? recipients.map(u => String(u.id)) : [];
                    }
                  }

                  const response = await projectMessagesService.create(newMessageProject, {
                    content: newMessageText,
                    subject: finalSubject,
                    priority: 'MEDIUM',
                    recipients: recipientsToSend
                  });

                  if (response.success) {
                    console.log('Message saved to database:', response.data);
                    // Refresh any project messages queries (match prefix)
                    queryClient.invalidateQueries({ queryKey: ['project-messages'] });
                  } else {
                    console.error('Failed to save message to database:', response.message);
                  }
                } catch (error) {
                  console.error('Error saving message:', error);
                }
              };

              // Call the API to save the message
              createMessage();
              
              // Also add to local state for immediate UI update
              const newActivity = {
                id: `msg_${Date.now()}`,
                projectId: parseInt(newMessageProject),
                projectName: selectedProject?.projectName || selectedProject?.name || selectedProject?.customer?.primaryName || selectedProject?.client?.name || selectedProject?.address || 'Unknown Project',
                projectNumber: selectedProject?.projectNumber || Math.floor(Math.random() * 90000) + 10000,
                subject: finalSubject,
                description: newMessageText,
                user: 'You',
                timestamp: new Date().toISOString(),
                type: 'message',
                priority: 'medium',
                recipients: newMessageRecipients
              };
              
              // Add to messages data
              setMessagesData(prev => [newActivity, ...prev]);
              setFeed(prev => [newActivity, ...prev]);
              
              // Close dropdown and reset form
              setShowMessageDropdown(false);
              setNewMessageProject('');
              setNewMessageSubject('');
              setNewMessageCustomSubject('');
              setNewMessageText('');
              setNewMessageRecipients([]);
            }
          }} className="space-y-2">
            {/* First Row: Project and To fields */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              <div>
                <label className={`block text-xs font-medium mb-1 ${
                  colorMode ? 'text-gray-300' : 'text-gray-700'
                }`}>
                  Project <span className="text-red-500">*</span>
                </label>
                <select
                  value={newMessageProject}
                  onChange={(e) => setNewMessageProject(e.target.value)}
                  required
                  className={`w-full px-2 py-1 border rounded text-xs ${
                    colorMode 
                      ? 'bg-[#232b4d] border-gray-600 text-white' 
                      : 'bg-white border-gray-300 text-gray-800'
                  }`}
                >
                  <option value="">Select Project</option>
                  {(projects || []).map(project => (
                    <option key={project.id} value={project.id}>
                      #{String(project.projectNumber || project.id).padStart(5, '0')} - {project.projectName || project.name || project.customer?.primaryName || project.client?.name || project.address}
                    </option>
                  ))}
                </select>
              </div>
              
              <div>
                <label className={`block text-xs font-medium mb-1 ${
                  colorMode ? 'text-gray-300' : 'text-gray-700'
                }`}>
                  To <span className="text-red-500">*</span>
                </label>
                <div className="flex justify-end -mt-3 mb-1">
                  <button title="Quick phrases" onClick={() => setIsQuickModalOpen(true)} className="text-xs px-2 py-1 rounded bg-gray-100">Quick Phrases</button>
                </div>
                
                {/* Primary Customer Contact Dropdown - Same style as Workflow Line Items */}
                {newMessageProject && (() => {
                  const selectedProject = projects.find(p => p.id === parseInt(newMessageProject));
                  const customer = selectedProject?.customer || selectedProject?.client;
                  if (customer) {
                    return (
                      <div className="mb-2 relative">
                        <div className="flex items-center gap-1">
                          <span className={`text-xs font-semibold ${colorMode ? 'text-gray-300' : 'text-gray-700'}`}>
                            📋 {customer.primaryName || customer.name || 'Customer'}
                          </span>
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              setShowCustomerDropdown(!showCustomerDropdown);
                            }}
                            className={`transform transition-transform duration-200 ${showCustomerDropdown ? 'rotate-180' : ''}`}
                          >
                            <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                            </svg>
                          </button>
                        </div>
                        
                        {/* Contact Details Popup */}
                        {showCustomerDropdown && (
                          <div className="absolute left-0 top-full mt-1 z-50 bg-white border border-gray-300 rounded-lg shadow-xl p-2.5 min-w-[180px] text-[10px] space-y-1">
                            <div className="font-semibold text-gray-900 border-b border-gray-200 pb-1 mb-1">
                              {customer.primaryName || customer.name || 'Customer'}
                            </div>
                            {customer.primaryPhone && (
                              <div className="flex items-start gap-1">
                                <span>📞</span>
                                <span className="text-gray-700">{customer.primaryPhone}</span>
                              </div>
                            )}
                            {customer.primaryEmail && (
                              <div className="flex items-start gap-1">
                                <span>📧</span>
                                <span className="text-gray-700 break-all">{customer.primaryEmail}</span>
                              </div>
                            )}
                            {customer.primaryAddress && (
                              <div className="flex items-start gap-1">
                                <span>📍</span>
                                <span className="text-gray-700">{customer.primaryAddress}</span>
                              </div>
                            )}
                            {!customer.primaryPhone && !customer.primaryEmail && !customer.primaryAddress && (
                              <div className="text-gray-500 italic text-[9px]">No contact details</div>
                            )}
                          </div>
                        )}
                      </div>
                    );
                  }
                  return null;
                })()}
                
                <select
                  value={Array.isArray(newMessageRecipients) ? newMessageRecipients : []}
                  onChange={(e) => {
                    const selectedOptions = Array.from(e.target.selectedOptions, option => option.value);
                    setNewMessageRecipients(selectedOptions);
                  }}
                  multiple
                  required
                  className={`w-full px-2 py-1 border rounded text-xs ${
                    colorMode 
                      ? 'bg-[#232b4d] border-gray-600 text-white' 
                      : 'bg-white border-gray-300 text-gray-800'
                  }`}
                  style={{ minHeight: '40px' }}
                >
                  <option value="all" style={{ fontWeight: 'bold' }}>All Users</option>
                  {usersLoading ? (
                    <option value="" disabled>Loading users...</option>
                  ) : recipients.length === 0 ? (
                    <option value="" disabled>No users found</option>
                  ) : (
                    recipients.map(user => (
                      <option key={user.id} value={user.id}>
                        {user.firstName} {user.lastName || ''} {user.lastName ? '' : `(${user.email || ''})`}
                      </option>
                    ))
                  )}
                </select>
                <p className={`text-[10px] mt-1 ${
                  colorMode ? 'text-gray-400' : 'text-gray-500'
                }`}>
                  Hold Ctrl/Cmd to select multiple recipients
                </p>
              </div>
            </div>
            
            {/* Second Row: Subject */}
            <div>
              <label className={`block text-xs font-medium mb-1 ${
                colorMode ? 'text-gray-300' : 'text-gray-700'
              }`}>
                Subject <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                placeholder="Enter subject line..."
                value={newMessageSubject}
                onChange={(e) => setNewMessageSubject(e.target.value)}
                required
                className={`w-full px-2 py-1 border rounded text-xs ${
                  colorMode 
                    ? 'bg-[#232b4d] border-gray-600 text-white placeholder-gray-400' 
                    : 'bg-white border-gray-300 text-gray-800 placeholder-gray-500'
                }`}
              />
            </div>
            
            <div>
              <label className={`block text-xs font-medium mb-1 ${
                colorMode ? 'text-gray-300' : 'text-gray-700'
              }`}>
                Message <span className="text-red-500">*</span>
              </label>
              <textarea
                value={newMessageText}
                onChange={(e) => setNewMessageText(e.target.value)}
                placeholder="Enter your message here..."
                required
                rows={2}
                className={`w-full px-2 py-1 border rounded text-xs resize-none ${
                  colorMode 
                    ? 'bg-[#232b4d] border-gray-600 text-white placeholder-gray-400' 
                    : 'bg-white border-gray-300 text-gray-800 placeholder-gray-500'
                }`}
              />
            </div>
            
            <div className="flex justify-end gap-1.5 pt-1">
              <button
                type="button"
                onClick={() => {
                  setShowMessageDropdown(false);
                  setNewMessageProject('');
                  setNewMessageSubject('');
                  setNewMessageCustomSubject('');
                  setNewMessageText('');
                  setNewMessageRecipients([]);
                }}
                className={`px-3 py-1.5 text-xs font-medium rounded border transition-colors ${
                  colorMode 
                    ? 'border-gray-600 text-gray-300 hover:bg-gray-700' 
                    : 'border-gray-300 text-gray-700 hover:bg-gray-50'
                }`}
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={!newMessageProject || !(newMessageSubject === 'CUSTOM_SUBJECT' ? newMessageCustomSubject : newMessageSubject) || !newMessageText.trim() || newMessageRecipients.length === 0}
                className={`px-3 py-1.5 text-xs font-medium rounded transition-colors ${
                  newMessageProject && (newMessageSubject === 'CUSTOM_SUBJECT' ? newMessageCustomSubject : newMessageSubject) && newMessageText.trim() && newMessageRecipients.length > 0
                    ? 'bg-[var(--color-primary-blueprint-blue)] text-white hover:bg-blue-700'
                    : 'bg-gray-300 text-gray-500 cursor-not-allowed'
                }`}
              >
                Send Message
              </button>
            </div>
          </form>
        </div>
      )}

      {/* In-app Quick Card Modal */}
      <CheatSheetModal visible={isQuickModalOpen} onClose={() => setIsQuickModalOpen(false)} colorMode={colorMode} />

      {/* Tasks Form */}
      {showMessageDropdown && activeCommTab === 'tasks' && (
        <div className={`p-2 border-t ${colorMode ? 'bg-[#1e293b] border-gray-600' : 'bg-gray-50 border-gray-200'}`}>
          <form onSubmit={async (e) => {
            e.preventDefault();
            if (!quickTaskDue) {
              toast.error('Due date is required');
              return;
            }
            
            // Get the actual user ID (handle both currentUser.id and currentUser.user.id)
            const userId = currentUser?.user?.id || currentUser?.id;
            if (!userId) {
              toast.error('User not found. Please refresh and try again.');
              return;
            }
            
            try {
              // Calculate endTime by adding timing duration to startTime
              const startTime = new Date(quickTaskDue);
              // Ensure minimum 1 minute duration if no timing is set
              const totalDuration = (taskTiming.days * 24 * 60 * 60 * 1000) + 
                (taskTiming.hours * 60 * 60 * 1000) + 
                (taskTiming.minutes * 60 * 1000);
              const duration = totalDuration > 0 ? totalDuration : 60 * 1000; // Default to 1 minute
              const endTime = new Date(startTime.getTime() + duration);
              
              // Create as calendar DEADLINE event; project optional
              const payload = {
                title: quickTaskSubject.trim() || 'Untitled Task',
                description: quickTaskDescription || '',
                startTime: quickTaskDue,
                endTime: endTime.toISOString().slice(0, 16), // Format as datetime-local
                eventType: 'DEADLINE',
                organizerId: userId,
                projectId: tasksProjectFilter || undefined,
                attendees: quickTaskAssignAll ? availableUsers.map(u => ({ userId: u.id })) : (quickTaskAssigneeId ? [{ userId: quickTaskAssigneeId }] : []),
                // Granular timing data
                timing: taskTiming,
                followUpTiming: taskFollowUpTiming.enabled ? taskFollowUpTiming : null
              };
              
              console.log('Creating task with payload:', payload);
              const res = await calendarService.create(payload);
              
              // Get the real ID from the API response
              const realEventId = res?.data?.event?.id || res?.data?.id;
              
              // Invalidate events so the task appears
              queryClient.invalidateQueries({ queryKey: queryKeys.calendarEvents });
              // Add to activity feed immediately
              // Determine assigned user for display
              console.log('🔍 Task creation debug:', {
                quickTaskAssignAll,
                quickTaskAssigneeId,
                availableUsersCount: availableUsers.length
              });
              
              let assignedToDisplay = 'Unassigned';
              if (quickTaskAssignAll) {
                assignedToDisplay = 'All Users';
              } else if (quickTaskAssigneeId && quickTaskAssigneeId.trim()) {
                console.log('🔍 Looking for user with ID:', quickTaskAssigneeId);
                console.log('🔍 Available users:', availableUsers.map(u => ({ id: u.id, name: u.name || `${u.firstName} ${u.lastName}` })));
                
                const assignedUser = availableUsers.find(u => String(u.id) === String(quickTaskAssigneeId));
                console.log('🔍 Found user:', assignedUser);
                
                if (assignedUser) {
                  // Try name first, then firstName + lastName, then email, then 'Unassigned'
                  if (assignedUser.name && assignedUser.name.trim()) {
                    assignedToDisplay = assignedUser.name;
                  } else if (assignedUser.firstName && assignedUser.firstName.trim() && assignedUser.lastName && assignedUser.lastName.trim()) {
                    assignedToDisplay = `${assignedUser.firstName} ${assignedUser.lastName}`;
                  } else if (assignedUser.firstName && assignedUser.firstName.trim()) {
                    assignedToDisplay = assignedUser.firstName;
                  } else if (assignedUser.email && assignedUser.email.trim()) {
                    assignedToDisplay = assignedUser.email;
                  } else {
                    assignedToDisplay = 'Unassigned';
                  }
                } else {
                  assignedToDisplay = 'Unassigned';
                }
              }
              
              console.log('🔍 Final assignedToDisplay:', assignedToDisplay);
              
              // Build attendees list for display
              const attendeesForDisplay = quickTaskAssignAll 
                ? availableUsers.map(u => u.id) 
                : (quickTaskAssigneeId ? [quickTaskAssigneeId] : []);
              
              setFeed(prev => [{
                id: realEventId || `cal_${Date.now()}`,
                type: 'task',
                authorId: userId,
                author: currentUser?.user ? `${currentUser.user.firstName} ${currentUser.user.lastName}` : (currentUser ? `${currentUser.firstName} ${currentUser.lastName}` : 'You'),
                assignedTo: assignedToDisplay,
                assigneeId: quickTaskAssigneeId || null,
                assignedToAll: quickTaskAssignAll || false,
                attendees: attendeesForDisplay,
                projectId: tasksProjectFilter || null,
                projectName: (projects.find(p => String(p.id) === String(tasksProjectFilter)) || {}).projectName || null,
                subject: quickTaskSubject.trim() || 'Untitled Task',
                content: quickTaskDescription || '',
                timestamp: quickTaskDue
              }, ...prev]);
              // Confirmation
              toast.success('Task created successfully');
              // Reset
              setQuickTaskSubject(''); setQuickTaskDescription(''); setQuickTaskDue(''); setQuickTaskAssignAll(false); setQuickTaskAssigneeId(''); setTasksProjectFilter('');
            } catch (err) {
              console.error('Failed to create task:', err);
              toast.error('Failed to create task');
            }
          }} className="space-y-2">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              <div>
                <label className={`block text-xs font-medium mb-1 ${colorMode ? 'text-gray-300' : 'text-gray-700'}`}>Project</label>
                <select 
                  value={tasksProjectFilter || ''} 
                  onChange={(e) => setTasksProjectFilter(e.target.value)} 
                  className={`w-full px-2 py-1 border rounded text-xs ${colorMode ? 'bg-[#232b4d] border-gray-600 text-white' : 'bg-white border-gray-300 text-gray-800'}`}
                >
                  <option value="">General (No Project)</option>
                  {(uiProjects || []).map(p => (
                    <option key={p.id} value={p.id}>
                      #{String(p.projectNumber || p.id).padStart(5, '0')} - {p.customer?.name || p.clientName || p.name}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className={`block text-xs font-medium mb-1 ${colorMode ? 'text-gray-300' : 'text-gray-700'}`}>Subject</label>
                <input value={quickTaskSubject} onChange={(e)=>setQuickTaskSubject(e.target.value)} className={`w-full px-2 py-1 border rounded text-xs ${colorMode ? 'bg-[#232b4d] border-gray-600 text-white' : 'bg-white border-gray-300 text-gray-800'}`} placeholder="Task subject (optional)" />
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              <div>
                <label className={`block text-xs font-medium mb-1 ${colorMode ? 'text-gray-300' : 'text-gray-700'}`}>Task Due Date <span className="text-red-500">*</span></label>
                <input type="datetime-local" value={quickTaskDue} onChange={(e)=>setQuickTaskDue(e.target.value)} className={`w-full px-2 py-1 border rounded text-xs ${colorMode ? 'bg-[#232b4d] border-gray-600 text-white' : 'bg-white border-gray-300 text-gray-800'}`} />
              </div>
              <div>
                <label className={`block text-xs font-medium mb-1 ${colorMode ? 'text-gray-300' : 'text-gray-700'}`}>Assign To</label>
                <select value={quickTaskAssigneeId} onChange={(e)=>{ setQuickTaskAssigneeId(e.target.value); setQuickTaskAssignAll(false); }} className={`w-full px-2 py-1 border rounded text-xs ${colorMode ? 'bg-[#232b4d] border-gray-600 text-white' : 'bg-white border-gray-300 text-gray-800'}`}>
                  <option value="">Unassigned</option>
                  {usersLoading ? (
                    <option value="" disabled>Loading users...</option>
                  ) : recipients.length === 0 ? (
                    <option value="" disabled>No users found</option>
                  ) : (
                    recipients.map(u => (
                      <option key={u.id} value={u.id}>
                        {u.firstName} {u.lastName || ''} {u.lastName ? '' : `(${u.email || ''})`}
                      </option>
                    ))
                  )}
                </select>
              </div>
            </div>
            <div>
              <label className={`block text-xs font-medium mb-1 ${colorMode ? 'text-gray-300' : 'text-gray-700'}`}>Description</label>
              <textarea value={quickTaskDescription} onChange={(e)=>setQuickTaskDescription(e.target.value)} rows={2} className={`w-full px-2 py-1 border rounded text-xs resize-none ${colorMode ? 'bg-[#232b4d] border-gray-600 text-white' : 'bg-white border-gray-300 text-gray-800'}`} />
            </div>
            
            {/* Granular Timing Controls for Tasks */}
            <GranularTimingControls
              colorMode={colorMode}
              timing={taskTiming}
              onTimingChange={setTaskTiming}
              showFollowUp={true}
              followUpTiming={taskFollowUpTiming}
              onFollowUpTimingChange={setTaskFollowUpTiming}
              label="Start Task"
            />
            <div className="flex items-center">
              <label className={`text-xs font-medium ${colorMode ? 'text-gray-300' : 'text-gray-700'}`}>
                <input type="checkbox" className="mr-1" checked={quickTaskAssignAll} onChange={(e)=>{ setQuickTaskAssignAll(e.target.checked); if (e.target.checked) setQuickTaskAssigneeId(''); }} /> Send to all users
              </label>
            </div>
            <div className="flex justify-end gap-1.5 pt-1">
              <button type="button" onClick={()=>{ setShowMessageDropdown(false); setQuickTaskSubject(''); setQuickTaskDescription(''); setQuickTaskDue(''); setQuickTaskAssignAll(false); setQuickTaskAssigneeId(''); setTasksProjectFilter(''); }} className={`px-3 py-1.5 text-xs font-medium rounded border transition-colors ${colorMode ? 'border-gray-600 text-gray-300 hover:bg-gray-700' : 'border-gray-300 text-gray-700 hover:bg-gray-50'}`}>Cancel</button>
              <button type="submit" disabled={!quickTaskDue} className={`px-3 py-1.5 text-xs font-medium rounded transition-colors ${quickTaskDue ? 'bg-[var(--color-primary-blueprint-blue)] text-white hover:bg-blue-700' : 'bg-gray-300 text-gray-500 cursor-not-allowed'}`}>Create Task</button>
            </div>
          </form>
        </div>
      )}

      {/* Reminders Form */}
      {showMessageDropdown && activeCommTab === 'reminders' && (
        <div className={`p-2 border-t ${colorMode ? 'bg-[#1e293b] border-gray-600' : 'bg-gray-50 border-gray-200'}`}>
          <form onSubmit={async (e) => {
            e.preventDefault();
            if (!reminderTitle.trim() || !reminderWhen) {
              toast.error('Title and date/time are required');
              return;
            }
            
            // Get the actual user ID (handle both currentUser.id and currentUser.user.id)
            const userId = currentUser?.user?.id || currentUser?.id;
            if (!userId) {
              toast.error('User not found. Please refresh and try again.');
              return;
            }
            
            try {
              // Calculate endTime by adding timing duration to startTime
              const startTime = new Date(reminderWhen);
              // Ensure minimum 1 minute duration if no timing is set
              const totalDuration = (reminderTiming.days * 24 * 60 * 60 * 1000) + 
                (reminderTiming.hours * 60 * 60 * 1000) + 
                (reminderTiming.minutes * 60 * 1000);
              const duration = totalDuration > 0 ? totalDuration : 60 * 1000; // Default to 1 minute
              const endTime = new Date(startTime.getTime() + duration);
              
              const payload = {
                title: reminderTitle.trim(),
                description: reminderDescription || '',
                startTime: reminderWhen,
                endTime: endTime.toISOString().slice(0, 16), // Format as datetime-local
                eventType: 'REMINDER',
                organizerId: userId,
                projectId: remindersProjectFilter || undefined,
                attendees: reminderAllUsers ? availableUsers.map(u => ({ userId: u.id })) : (reminderUserIds.length ? reminderUserIds.map(id => ({ userId: id })) : []),
                // Granular timing data
                timing: reminderTiming,
                followUpTiming: reminderFollowUpTiming.enabled ? reminderFollowUpTiming : null
              };
              
              console.log('Creating reminder with payload:', payload);
              const res = await calendarService.create(payload);
              
              // Get the real ID from the API response
              const realEventId = res?.data?.event?.id || res?.data?.id;
              
              // Invalidate events so the reminder appears
              queryClient.invalidateQueries({ queryKey: queryKeys.calendarEvents });
              // Add to activity feed immediately
              // Build recipients list for display
              const recipientsForDisplay = reminderAllUsers 
                ? availableUsers.map(u => u.id) 
                : (reminderUserIds.length ? reminderUserIds : []);
              
              setFeed(prev => [{
                id: realEventId || `cal_${Date.now()}`,
                type: 'reminder',
                authorId: userId,
                author: currentUser?.user ? `${currentUser.user.firstName} ${currentUser.user.lastName}` : (currentUser ? `${currentUser.firstName} ${currentUser.lastName}` : 'You'),
                recipients: recipientsForDisplay,
                projectId: remindersProjectFilter || null,
                projectName: (projects.find(p => String(p.id) === String(remindersProjectFilter)) || {}).projectName || null,
                subject: reminderTitle.trim(),
                content: reminderDescription || '',
                timestamp: reminderWhen
              }, ...prev]);
              toast.success('Reminder created successfully');
              setReminderTitle(''); setReminderDescription(''); setReminderWhen(''); setReminderAllUsers(false); setReminderUserIds([]);
            } catch (err) {
              console.error('Failed to create reminder:', err);
              toast.error('Failed to create reminder');
            }
          }} className="space-y-2">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              <div>
                <label className={`block text-xs font-medium mb-1 ${colorMode ? 'text-gray-300' : 'text-gray-700'}`}>Title <span className="text-red-500">*</span></label>
                <input value={reminderTitle} onChange={(e)=>setReminderTitle(e.target.value)} className={`w-full px-2 py-1 border rounded text-xs ${colorMode ? 'bg-[#232b4d] border-gray-600 text-white' : 'bg-white border-gray-300 text-gray-800'}`} placeholder="Reminder title" />
              </div>
              <div>
                <label className={`block text-xs font-medium mb-1 ${colorMode ? 'text-gray-300' : 'text-gray-700'}`}>When <span className="text-red-500">*</span></label>
                <input type="datetime-local" value={reminderWhen} onChange={(e)=>setReminderWhen(e.target.value)} className={`w-full px-2 py-1 border rounded text-xs ${colorMode ? 'bg-[#232b4d] border-gray-600 text-white' : 'bg-white border-gray-300 text-gray-800'}`} />
              </div>
            </div>
            <div>
              <label className={`block text-xs font-medium mb-1 ${colorMode ? 'text-gray-300' : 'text-gray-700'}`}>Description</label>
              <textarea value={reminderDescription} onChange={(e)=>setReminderDescription(e.target.value)} rows={2} className={`w-full px-2 py-1 border rounded text-xs resize-none ${colorMode ? 'bg-[#232b4d] border-gray-600 text-white' : 'bg-white border-gray-300 text-gray-800'}`} />
            </div>
            
            {/* Granular Timing Controls for Reminders */}
            <GranularTimingControls
              colorMode={colorMode}
              timing={reminderTiming}
              onTimingChange={setReminderTiming}
              showFollowUp={true}
              followUpTiming={reminderFollowUpTiming}
              onFollowUpTimingChange={setReminderFollowUpTiming}
              label="Start Reminder"
            />
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              <div>
                <label className={`block text-xs font-medium mb-1 ${colorMode ? 'text-gray-300' : 'text-gray-700'}`}>Recipients</label>
                <select 
                  multiple 
                  value={reminderUserIds} 
                  onChange={(e)=>setReminderUserIds(Array.from(e.target.selectedOptions, o => o.value))} 
                  className={`w-full px-2 py-1 border rounded text-xs ${colorMode ? 'bg-[#232b4d] border-gray-600 text-white' : 'bg-white border-gray-300 text-gray-900'}`} 
                  style={{ minHeight: '40px', color: colorMode ? '#ffffff' : '#111827' }}
                >
                  {usersLoading ? (
                    <option value="" disabled style={{ color: '#111827', backgroundColor: '#ffffff' }}>Loading users...</option>
                  ) : recipients.length === 0 ? (
                    <option value="" disabled style={{ color: '#111827', backgroundColor: '#ffffff' }}>No users found</option>
                  ) : (
                    recipients.map(u => (
                      <option key={u.id} value={u.id} style={{ color: '#111827', backgroundColor: '#ffffff' }}>
                        {u.firstName} {u.lastName || ''} {u.lastName ? '' : `(${u.email || ''})`}
                      </option>
                    ))
                  )}
                </select>
                <p className={`text-[10px] mt-1 ${colorMode ? 'text-gray-400' : 'text-gray-500'}`}>Hold Ctrl/Cmd to select multiple recipients</p>
              </div>
              <div className="flex items-end">
                <label className={`text-xs font-medium ${colorMode ? 'text-gray-300' : 'text-gray-700'}`}>
                  <input type="checkbox" className="mr-1" checked={reminderAllUsers} onChange={(e)=>{ setReminderAllUsers(e.target.checked); if (e.target.checked) setReminderUserIds([]); }} /> Send to all users
                </label>
              </div>
            </div>
            <div className="flex justify-end gap-1.5 pt-1">
              <button type="button" onClick={()=>{ setShowMessageDropdown(false); setReminderTitle(''); setReminderDescription(''); setReminderWhen(''); setReminderAllUsers(false); setReminderUserIds([]); }} className={`px-3 py-1.5 text-xs font-medium rounded border transition-colors ${colorMode ? 'border-gray-600 text-gray-300 hover:bg-gray-700' : 'border-gray-300 text-gray-700 hover:bg-gray-50'}`}>Cancel</button>
              <button type="submit" disabled={!reminderTitle.trim() || !reminderWhen} className={`px-3 py-1.5 text-xs font-medium rounded transition-colors ${reminderTitle.trim() && reminderWhen ? 'bg-[var(--color-primary-blueprint-blue)] text-white hover:bg-blue-700' : 'bg-gray-300 text-gray-500 cursor-not-allowed'}`}>Create Reminder</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default MTRForm;